function cookieVal(req,name){const m=new RegExp("(?:^|;\\s*)"+name+"=([^;]+)").exec(req.headers.get("Cookie")||"");return m?m[1]:""}
async function hmac(secret,value){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(secret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);const sig=await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(value));return [...new Uint8Array(sig)].map(x=>x.toString(16).padStart(2,"0")).join("")}
async function authed(req,env){const t=cookieVal(req,"kk_admin");const [exp,sig]=t.split(".");if(!exp||!sig||Number(exp)<Date.now()||!env.SESSION_SECRET)return false;return await hmac(env.SESSION_SECRET,exp)===sig}
function sameOrigin(req){const o=req.headers.get("Origin");return !o||new URL(o).host===new URL(req.url).host}
async function parse(req,max=2000000){const txt=await req.text();if(txt.length>max)throw new Error("Request too large");try{return JSON.parse(txt||"{}")}catch(e){throw new Error("Invalid JSON")}}
function clean(c){if(!c||typeof c!=="object"||Array.isArray(c))throw new Error("Invalid content");const next={...DEFAULTS};for(const [k,v] of Object.entries(c)){if(!(k in DEFAULTS))continue;const f=String(k);if(/^offer\.discount[123]$/.test(f)){const n=String(v).replace(/%/g,"").trim();if(!/^\d{1,3}$/.test(n)||Number(n)>100)throw new Error(f+": enter a number from 0 to 100");next[k]=n}else if(typeof DEFAULTS[k]==="boolean")next[k]=!!v;else if(Array.isArray(DEFAULTS[k]))next[k]=Array.isArray(v)?v.slice(0,30):DEFAULTS[k];else if(typeof v==="string")next[k]=v.replace(/[\u0000-\u001F]/g,"").slice(0,5000);else next[k]=v}return next}
async function handle(request,env,ctx){const u=new URL(request.url),p=decodeURIComponent(u.pathname);if(p==="/api/admin/status"&&request.method==="GET")return json({adminPasswordConfigured:!!env.ADMIN_PASSWORD,sessionSecretConfigured:!!env.SESSION_SECRET,kvConfigured:!!env.KK_DATA});if(p==="/api/content"&&request.method==="GET")return json(await getContent(env));if(p==="/api/visual-layout"&&request.method==="GET"){const layout=await env.KK_DATA.get("visual-layout-live","json"),mobileLayout=await env.KK_DATA.get("visual-layout-mobile-live","json");return json({layout:layout&&typeof layout==="object"?layout:{},mobileLayout:mobileLayout&&typeof mobileLayout==="object"?mobileLayout:{}})}if(p.startsWith("/api/admin/")){if(!sameOrigin(request))return json({error:"Bad origin"},403);if(p==="/api/admin/login"&&request.method==="POST"){const b=await parse(request,5000);if(!env.ADMIN_PASSWORD||!env.SESSION_SECRET){const missing=[];if(!env.ADMIN_PASSWORD)missing.push("ADMIN_PASSWORD");if(!env.SESSION_SECRET)missing.push("SESSION_SECRET");return json({error:"Missing Cloudflare Production secret(s): "+missing.join(", "),missing},500);}if(String(b.password||"")!==env.ADMIN_PASSWORD)return json({error:"Wrong password"},401);const exp=String(Date.now()+12*60*60*1000),sig=await hmac(env.SESSION_SECRET,exp);return json({ok:true},200,{"Set-Cookie":`kk_admin=${exp}.${sig}; HttpOnly;${u.protocol==="https:"?" Secure;":""} SameSite=Strict; Path=/; Max-Age=43200`})}if(p==="/api/admin/logout")return json({ok:true},200,{"Set-Cookie":`kk_admin=; HttpOnly;${u.protocol==="https:"?" Secure;":""} SameSite=Strict; Path=/; Max-Age=0`});if(!await authed(request,env))return json({error:"Please log in"},401);if(p==="/api/admin/content"&&request.method==="GET")return json({schema:SCHEMA,content:await getContent(env),defaults:DEFAULTS});if(p==="/api/admin/visual-layout"&&request.method==="GET"){const draft=await env.KK_DATA.get("visual-layout-draft","json"),live=await env.KK_DATA.get("visual-layout-live","json"),mobileDraft=await env.KK_DATA.get("visual-layout-mobile-draft","json"),mobileLive=await env.KK_DATA.get("visual-layout-mobile-live","json");return json({draft:draft&&typeof draft==="object"?draft:{},live:live&&typeof live==="object"?live:{},mobileDraft:mobileDraft&&typeof mobileDraft==="object"?mobileDraft:{},mobileLive:mobileLive&&typeof mobileLive==="object"?mobileLive:{}})}if(p==="/api/admin/visual-layout"&&request.method==="PUT"){try{const b=await parse(request,100000);if(!b.layout||typeof b.layout!=="object"||Array.isArray(b.layout)||Object.keys(b.layout).length>300)return json({error:"Invalid visual layout"},400);const cleanLayout={};for(const [selector,v] of Object.entries(b.layout)){if(typeof selector!=="string"||selector.length>700||/[<{};]/.test(selector)||!v||typeof v!=="object")continue;cleanLayout[selector]={x:Math.max(-1500,Math.min(1500,Number(v.x)||0)),y:Math.max(-1500,Math.min(1500,Number(v.y)||0)),width:v.width?Math.max(5,Math.min(300,Number(v.width))):0,height:v.height?Math.max(40,Math.min(3000,Number(v.height))):0,hidden:!!v.hidden,deleted:!!v.deleted,color:/^#[0-9a-fA-F]{6}$/.test(v.color||"")?v.color:"",backgroundColor:/^#[0-9a-fA-F]{6}$/.test(v.backgroundColor||"")?v.backgroundColor:"",textAlign:["left","center","right"].includes(v.textAlign)?v.textAlign:"",fontSize:v.fontSize?Math.max(8,Math.min(120,Number(v.fontSize))):0,borderRadius:v.borderRadius?Math.max(0,Math.min(100,Number(v.borderRadius))):0,padding:v.padding?Math.max(0,Math.min(120,Number(v.padding))):0,text:typeof v.text==="string"?v.text.slice(0,1000):undefined,href:typeof v.href==="string"&&v.href.length<1000&&!/^\s*javascript:/i.test(v.href)?v.href:undefined,src:typeof v.src==="string"&&v.src.length<1000&&!/^\s*javascript:/i.test(v.src)?v.src:undefined}}const mobile=b.device==="mobile",draftKey=mobile?"visual-layout-mobile-draft":"visual-layout-draft";await env.KK_DATA.put(draftKey,JSON.stringify(cleanLayout));return json({ok:true,draft:cleanLayout,device:mobile?"mobile":"desktop"})}catch(e){return json({error:e.message},400)}}if(p==="/api/admin/visual-layout/publish"&&request.method==="POST"){const b=await parse(request,5000),mobile=b.device==="mobile",draft=await env.KK_DATA.get(mobile?"visual-layout-mobile-draft":"visual-layout-draft","json")||{};await env.KK_DATA.put(mobile?"visual-layout-mobile-live":"visual-layout-live",JSON.stringify(draft));return json({ok:true,layout:draft,device:mobile?"mobile":"desktop"})}if(p==="/api/admin/content"&&request.method==="PUT"){try{const c=clean(await parse(request));await saveContent(env,c);return json({ok:true,content:c})}catch(e){return json({error:e.message},400)}}if(p==="/api/admin/reset"&&request.method==="POST"){await saveContent(env,{...DEFAULTS});return json({ok:true,content:DEFAULTS})}if(p==="/api/admin/upload"&&request.method==="POST"){try{const b=await parse(request,8000000),m=/^data:image\/(png|jpeg|webp|gif);base64,([A-Za-z0-9+/=]+)$/.exec(b.data||"");if(!m)return json({error:"Upload a PNG, JPG, WebP or GIF image"},400);const raw=atob(m[2]);if(raw.length>5*1024*1024)return json({error:"Image must be under 5 MB"},400);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));const good=(m[1]==="png"&&raw.startsWith("\x89PNG"))||(m[1]==="jpeg"&&bytes[0]===255&&bytes[1]===216)||(m[1]==="webp"&&raw.slice(0,4)==="RIFF"&&raw.slice(8,12)==="WEBP")||(m[1]==="gif"&&raw.startsWith("GIF8"));if(!good)return json({error:"File is not a valid image"},400);const ext=m[1]==="jpeg"?"jpg":m[1],name=Date.now().toString(36)+crypto.randomUUID().slice(0,8)+"."+ext;await env.KK_DATA.put("upload:"+name,JSON.stringify({type:"image/"+(m[1]==="jpeg"?"jpeg":m[1]),data:b.data.split(",")[1]}));return json({url:"/uploads/"+name})}catch(e){return json({error:e.message},400)}}return json({error:"Not found"},404)}if(p.startsWith("/uploads/")){const name=p.slice(9);if(!/^[a-z0-9-]+\.(png|jpg|webp|gif)$/.test(name))return new Response("Not found",{status:404});const item=await env.KK_DATA.get("upload:"+name,"json");if(!item)return new Response("Not found",{status:404});const raw=atob(item.data),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));return new Response(bytes,{headers:{"Content-Type":item.type,"Cache-Control":"public, max-age=86400",...SEC}})}if(p==="/about-us"||p==="/about-us/")return renderAbout(await getContent(env));const friendlyPages={"/contact-us":"/pages/contact-us.html","/faq":"/pages/faq.html","/shipping-returns":"/pages/shipping-returns.html","/order-tracking":"/pages/order-tracking.html","/shipping-information":"/pages/shipping-information.html","/returns-exchanges":"/pages/returns-exchanges.html","/payment-methods":"/pages/payment-methods.html","/terms-conditions":"/pages/terms-conditions.html","/privacy-policy":"/pages/privacy-policy.html"};if(friendlyPages[p])return ctx.next(new Request(new URL(friendlyPages[p],u),{method:"GET",headers:request.headers}));if(p==="/"||p==="/index.html")return render(await getContent(env),env,request);if(p==="/admin"||p==="/admin/")return ctx.next(new Request(new URL("/admin/index.html",u),{method:"GET",headers:request.headers}));if(p==="/shop"||p==="/shop/")return ctx.next(new Request(new URL("/shop.html"+u.search,u),{method:request.method,headers:request.headers}));if(p==="/product"||p==="/product/"){const target=new URL("/product.html"+u.search,u);return ctx.next(new Request(target,{method:request.method,headers:request.headers}))}if(p.startsWith("/product/")){const handle=p.slice("/product/".length).replace(/\/$/,"");if(!handle)return ctx.next(new Request(new URL("/shop.html"+u.search,u),{method:request.method,headers:request.headers}));const target=new URL("/product.html",u);target.searchParams.set("handle",handle);u.searchParams.forEach((v,k)=>{if(k!=="handle")target.searchParams.set(k,v)});return ctx.next(new Request(target,{method:request.method,headers:request.headers}))}return ctx.next()}
export async function onRequest(context){try{return await handle(context.request,context.env,context)}catch(e){return json({error:"Server error",detail:e.message},500)}}
